
-- Remove older duplicate so canonical custom slug can be inserted
DELETE FROM public.projects WHERE slug = 'rajapushpa-sierra';

ON CONFLICT (slug) DO UPDATE SET
  custom_page_path = EXCLUDED.custom_page_path,
  canonical_url = EXCLUDED.canonical_url,
  featured = true,
  hero_image = COALESCE(public.projects.hero_image, EXCLUDED.hero_image);
